@Override public Function newInstance(int position, ObjList<Function> args, IntList argPositions, CairoConfiguration configuration, SqlExecutionContext sqlExecutionContext) throws SqlException {
  Function countFunc;
  final Function seedLoFunc;
  final Function seedHiFunc;
  if (args != null) {
    final int argCount=args.size();
    if (argCount == 1 && ColumnType.isAssignableFrom((countFunc=args.getQuick(0)).getType(), ColumnType.LONG)) {
      return new CursorFunction(new LongSequenceCursorFactory(METADATA, countFunc.getLong(null)));
    }
    if (argCount > 2 && ColumnType.isAssignableFrom((countFunc=args.getQuick(0)).getType(), ColumnType.LONG) && ColumnType.isAssignableFrom((seedLoFunc=args.getQuick(1)).getType(), ColumnType.LONG) && ColumnType.isAssignableFrom((seedHiFunc=args.getQuick(2)).getType(), ColumnType.LONG)) {
      return new CursorFunction(new SeedingLongSequenceCursorFactory(METADATA, countFunc.getLong(null), seedLoFunc.getLong(null), seedHiFunc.getLong(null)));
    }
  }
  try {
    throw SqlException.position(position).put("invalid arguments");
  } catch (IndexOutOfBoundsException e) {
    throw SqlException.position(0).put("invalid arguments");
  }
}
